import numpy as np
from scipy import linalg


def rosenbrock(x):
    return 100.0 * (x[1] - x[0] ** 2) ** 2 + (1.0 - x[0]) ** 2


def rosenbrock_grad(x):
    return np.array(
        [-400.0 * x[0] * (x[1] - x[0] ** 2) - 2.0 * (1.0 - x[0]),
         200.0 * (x[1] - x[0] ** 2)]
    )


def rosenbrock_hess(x):
    return np.array(
        [[-400.0 * (x[1] - 3.0 * x[0] ** 2) + 2.0, -400.0 * x[0]],
         [-400.0 * x[0], 200.0]]
    )


def sr1_update(B, s, y, r=1e-8):
    """SR1 update (Quasi-Newton Methods notebook), skipping tiny denominators."""
    u = y - B @ s
    if abs(u @ s) <= r * linalg.norm(u) * linalg.norm(s):
        return B
    return B + np.outer(u, u) / (u @ s)


def bfgs_update(B, s, y, C2=1e-8):
    """BFGS update (Quasi-Newton Methods notebook), skipping small curvature."""
    if s @ y < C2 * (s @ s):
        return B
    Bs = B @ s
    return B + np.outer(y, y) / (s @ y) - np.outer(Bs, Bs) / (s @ Bs)


def no_update(B, s, y):
    return B  # steepest descent keeps B = I


